const freeMembership=()=>({plan:'free',playlist_limit:2,owned_count:0,active_ids:[],locked_count:0,full_lyrics:false,premium_until:null,checkout_available:false});
let member=freeMembership(),membershipTimer;
function setMembership(value){
 member=value||freeMembership();clearTimeout(membershipTimer);
 window.AifectAudioAds?.setMembership(member,me?.id);
 if(!member.full_lyrics&&typeof clearFullLyrics==='function')clearFullLyrics();
 if(member.premium_until){const delay=member.premium_until*1000-Date.now();if(delay>0)membershipTimer=setTimeout(async()=>{try{await refreshLibrary();updateAccount();if(/^(#membership|#library|#playlist|#account)/.test(location.hash))await render();}catch{member={...member,plan:'free',full_lyrics:false,playlist_limit:2};clearFullLyrics();}},Math.min(delay+100,2147483647));}
}
function membershipHTML(billing){return heading('나에게 맞는 AIFECT','전체곡은 무료로 듣고, 취향을 모으는 방법을 선택하세요.')+billingHTML(billing)+`<div class="membership-grid"><article class="surface membership-card"><span class="eyebrow">FREE</span><h2>무료</h2><p>좋아하는 음악과 함께하는 일상</p><ul><li>전체곡 무료 감상</li><li>재생 중인 가사 한 줄 표시</li><li>내 플레이리스트 최대 2개</li><li>좋아요 · 공개 플레이리스트 저장</li></ul><span class="plan-state">${member.plan==='free'?'현재 이용 중':'무료 플랜'}</span></article><article class="surface membership-card premium-card"><span class="eyebrow">PREMIUM</span><h2>Premium</h2><p class="plan-price">월 ${AifectSite.PREMIUM.price.toLocaleString('ko-KR')}원 <small>부가세 포함</small></p><p>1개월 이용권 · 매월 정기결제</p><ul><li>전체곡 감상</li><li>전체 가사 · 현재 줄 강조 · 자동 스크롤</li><li>가사를 누르면 해당 구간으로 이동</li><li>내 플레이리스트 최대 10개</li></ul><span class="plan-state">${member.plan==='premium'?'현재 이용 중':billing?.checkout_available?'지금 가입 가능':'가입 준비 중'}</span></article></div><p class="field-help">공개 플레이리스트 저장은 생성 한도에 포함되지 않습니다. 무료로 전환하면 기존 목록을 보관하고, 사용할 2개를 선택할 수 있어요.</p><nav class="plan-summary-links" aria-label="이용권 안내"><a href="/pricing" target="_blank" rel="noopener">상세 상품 정보</a><a href="/refund" target="_blank" rel="noopener">환불 · 해지 정책</a><a href="/terms" target="_blank" rel="noopener">이용약관</a></nav>${me?'<a class="small-button" href="#library/playlists">내 플레이리스트 관리 →</a>':'<a class="primary-button" href="#account">무료로 시작하기 →</a>'}`;}
function playlistQuotaHTML(){return `<div class="playlist-quota"><div><strong>${member.plan==='premium'?'Premium':'무료'} · 내 플레이리스트 ${member.owned_count} / ${member.playlist_limit}개</strong><p>다른 사람이 만든 공개 목록은 개수 제한 없이 저장할 수 있어요.${member.locked_count?` 현재 ${member.locked_count}개는 보관 중입니다.`:''}</p></div><div class="inline-actions">${member.locked_count?'<button class="small-button" data-select-active>사용할 목록 선택</button>':''}<a class="text-link" href="#membership">이용 혜택 보기 →</a></div></div>`;}
function canCreatePlaylist(){
 if(member.owned_count<member.playlist_limit)return true;
 dialog(`<h2>플레이리스트 ${member.playlist_limit}개를 모두 만들었어요.</h2><p>${member.plan==='premium'?'Premium은 최대 10개':'무료 회원은 최대 2개'}까지 만들 수 있습니다. 기존 목록에 곡을 더 담거나, 필요 없는 목록을 삭제한 뒤 만들어주세요.</p>${member.locked_count?'<button class="small-button" data-select-active>사용할 목록 선택</button>':''}<a class="text-link" href="#membership" data-close-dialog>이용 혜택 보기 →</a>`);return false;
}
async function selectActivePlaylists(){
 if(!me)return askLogin();await refreshLibrary();const count=Math.min(member.playlist_limit,library.playlists.length);
 dialog(`<h2>사용할 플레이리스트 선택</h2><p>${count}개를 선택해주세요. 선택하지 않은 목록과 담긴 곡은 보관됩니다.</p><form id="active-playlist-form"><div class="active-playlist-picker">${library.playlists.map(p=>`<label class="checkbox-line"><input type="checkbox" name="playlist_ids" value="${p.id}" ${member.active_ids.includes(p.id)?'checked':''}><span><strong>${esc(p.name)}</strong><small>${p.tracks}곡${p.locked?' · 보관 중':''}</small></span></label>`).join('')}</div><output id="active-playlist-count"></output><button class="primary-button">선택한 목록 사용하기</button><p class="form-error" role="alert"></p></form>`);
 const form=$('#active-playlist-form'),update=()=>{const n=form.querySelectorAll('input:checked').length;$('#active-playlist-count').textContent=`${n} / ${count}개 선택`;form.querySelector('button').disabled=n!==count;};form.onchange=update;update();
 form.onsubmit=busyForm(form,async fd=>{await api('/api/library/playlists/active','PUT',{playlist_ids:fd.getAll('playlist_ids')});$('#dialog').close();await refreshLibrary();await render();toast('사용할 플레이리스트를 저장했습니다.');});
}
function lockedPlaylistHTML(p){return heading(esc(p.name),'이 플레이리스트는 보관 중입니다.')+`<section class="surface membership-card"><h2>담아둔 음악은 그대로 있어요.</h2><p>${p.tracks}곡이 보관되어 있습니다. 사용할 목록으로 선택하면 다시 재생하고 편집할 수 있어요.</p><div class="inline-actions"><button class="primary-button" data-select-active>사용할 목록 선택</button><a class="small-button" href="#library/playlists">내 보관함</a><button class="text-link" data-delete-playlist="${p.id}">이 목록 삭제</button></div></section>`;}
document.addEventListener('click',e=>{if(e.target.closest('[data-select-active]'))selectActivePlaylists().catch(err=>toast(err.message));if(e.target.closest('[data-close-dialog]'))$('#dialog').close();});
